from lib import *
S = SS('g70')
steps = [
    step("消费者提前走掉:没有取消机制的流水线,100 条各只读 3 个元素就丢弃,goroutine 数 1 → 101(每条泄漏 1 个,卡在 out <- i 上)。同样 100 条两级流水线,读 3 个后调用 cancel():goroutine 数 101 → 101(起点的 101 包含上一组已泄漏的 100 个,这一组没有新增)。", t=tl(S(1)), done=lidx(S(1), '读 3 个后 cancel()'), mark=lidx(S(1), '没有取消机制'), b=bars([['无取消:新增 goroutine', 100, '+100'], ['有 cancel:新增 goroutine', 0, '+0']], 100, mark=[0], done=[1]), kv=KV([['无取消', '100 条泄漏 100 个 goroutine'], ['有 cancel', '没有新增'], ['做法', '每一级 send 都和 ctx.Done() 一起 select']], ['做法'])),
    step("fan-out 并行处理 0..1999(4 个 worker,每个元素睡 0/100/200 µs),fan-in 合并之后:收到 2000 个,元素齐全,但输出里“比前一个小”的位置有 794 处——顺序被打乱了。需要顺序就要在合并后按序号重排,或不用 fan-out。", t=tl(S(2)), mark=lidx(S(2), '794 处'), kv=KV([['元素', '2000 个全部收到'], ['顺序', '794 处逆序'], ['含义', 'fan-out 换来并行,代价是顺序']], ['含义'])),
    step("第二级每个元素约 20000 次乘加,增加 worker 数:1 个 596 ms;2 个 320 ms;4 个 176 ms;8 个 114 ms(8 个 P)。8 个 worker 比 1 个快约 5.2 倍,没有达到 8 倍,因为生成与合并阶段也要占 CPU。", t=tl(S(3)), done=lidx(S(3), 'worker 数 = 1', 'worker 数 = 2'), mark=lidx(S(3), 'worker 数 = 4', 'worker 数 = 8'), b=bars([['1 个 worker (ms)', 596, '596'], ['2 个', 320, '320'], ['4 个', 176, '176'], ['8 个', 114, '114']], 596, done=[0], mark=[1, 2, 3]), kv=KV([['1 → 8 个 worker', '596 → 114 ms,约 5.2 倍'], ['没到 8 倍', '生成与合并也占 CPU(推测)']], ['没到 8 倍'])),
    step("几乎不做事的三级流水线,每级 channel 的容量对吞吐的影响:容量 0:100 万个元素 594 ms,594 ns/个;容量 1:419 ns/个;容量 16:229 ns/个;容量 256:129 ms,129 ns/个。缓冲区越大,级间的同步越少。", t=tl(S(4)), mark=lidx(S(4), '容量   0', '容量   1', '容量  16', '容量 256'), b=bars([['容量 0 (ns/个)', 594, '594'], ['容量 1', 419, '419'], ['容量 16', 229, '229'], ['容量 256', 129, '129']], 594, done=[3], mark=[0, 1, 2]), kv=KV([['无缓冲', '594 ns/个'], ['容量 256', '129 ns/个,约 4.6 倍'], ['代价', '更多元素排队、背压更晚']], ['代价'])),
]
A = mkartg('g70', 70, 'Go,channel,流水线,fan-out,fan-in,取消,真实验证,动画演示',
    '在 Go 1.27.1 里实测 channel 流水线:消费者提前走掉而没有取消机制时泄漏 100 个 goroutine,加 cancel 后为 0;4 个 worker fan-out 后输出有 794 处逆序;第二级 worker 从 1 个增加到 8 个,2 万个元素从 596 ms 降到 114 ms(约 5.2 倍);级间 channel 容量从 0 加到 256,每个元素的耗时从 594 ns 降到 129 ns。',
    '用 channel 串起来的流水线写起来简单,但有三个实际问题:消费者提前走了怎么办、并行之后顺序怎么办、缓冲区开多大。这篇用真实运行回答,并量并行 worker 数的收益。',
    [('+100 vs +0', '消费者提前走掉时,无取消机制与有 cancel 的流水线新增的 goroutine 数'), ('794 处', '4 个 worker 并行后,2000 个元素的输出里出现逆序的位置'), ('594 → 129 ns', '级间 channel 容量从 0 到 256,每个元素的耗时')],
    [('取消是必须的', '<p>每一级发送都只用 <code>out &lt;- v</code>,消费者读了 3 个就走,上游 goroutine 永远卡在发送上,100 条流水线泄漏 100 个。每一级把发送和 <code>ctx.Done()</code> 放进同一个 <code>select</code>,<code>cancel()</code> 之后全部退出。</p>'),
     ('fan-out 会乱序', '<p>4 个 worker 并行处理、再合并,2000 个元素全部收到,但顺序不再是输入的顺序(794 处逆序)。需要顺序就要带序号并在合并后排序。</p>'),
     ('worker 数的收益', '<p>瓶颈在第二级且是 CPU 计算时,1、2、4、8 个 worker 分别用 596、320、176、114 ms。到 8 个时没有 8 倍的加速,我推测是生成和合并阶段的 goroutine 也在抢 CPU,没有验证。</p>'),
     ('缓冲区', '<p>三级几乎不做事的流水线,容量 0 时每个元素 594 ns,容量 256 时 129 ns,因为级间交接不用每次都等对方。但缓冲区只是在摊薄同步成本,并不改变整体的吞吐上限,而且会让背压来得更晚。</p>')],
    steps,
    [ENV_G + '。泄漏实验用 runtime.NumGoroutine,读完 3 个元素后等 50 ms;乱序实验的处理时间由 time.Sleep 制造;并行实验的重负载函数是 2 万次乘加,GOMAXPROCS=8;缓冲实验三个 goroutine 串联,每个设置单次测量',
     '没有验证:有序 fan-in 的写法及其代价、errgroup 与流水线结合、channel 关闭时机的其它错误模式、更多级数时的开销、泄漏 goroutine 的内存占用(单个约 2 KB 的说法没有在本文测量)'],
    'channel 流水线')
